# Copia de seguridad cifrada y preparacion de traslado. Uso: python3 install11.py
import os,subprocess,sys,base64
F={'/root/vibk_backup.sh':'','/root/vibk_restore.sh':'','/root/GUIA_TRASLADO.txt':''}
for p,c in F.items():
    open(p,'wb').write(base64.b64decode(c)); os.chmod(p,0o700 if p.endswith('.sh') else 0o600)
P='/root/.vibk_backup_pass'
if not (os.path.exists(P) and os.path.getsize(P)>10):
    k=subprocess.run(['openssl','rand','-base64','24'],capture_output=True,text=True).stdout.strip()
    open(P,'w').write(k+'\n'); print('Contraseña de copias creada (no se muestra aqui).')
os.chmod(P,0o600)
open('/etc/cron.d/vibk_backup','w').write('# VIBKAPTUR: copia cifrada semanal (domingos 03:15)\n15 3 * * 0 root /root/vibk_backup.sh >> /root/vibk_backups/copias.log 2>&1\n')
os.makedirs('/root/vibk_backups',exist_ok=True); os.chmod('/root/vibk_backups',0o700)
r=subprocess.run(['bash','/root/vibk_backup.sh'],capture_output=True,text=True)
print((r.stdout or '').strip()[-400:]); 
if r.returncode!=0: print('FALLO al hacer la copia:',(r.stderr or '')[-400:]); sys.exit(1)
print('COPIAS INSTALADAS. Ahora apunta la contraseña:  cat /root/.vibk_backup_pass   (no me la mandes)')
